<?php
require __DIR__ . '/backend/common.php'; require_admin(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$project_id=(int)input('project_id');$user_id=(int)input('user_id');$decision=input('decision');if(!in_array($decision,['approved','rejected'],true))throw new InvalidArgumentException('Invalid decision.');$request=$conn->execute_query("SELECT r.*,p.title FROM project_join_requests r JOIN projects p ON p.id=r.project_id WHERE r.project_id=? AND r.user_id=? AND r.status='pending'",[$project_id,$user_id])->fetch_assoc();if(!$request)throw new InvalidArgumentException('Request is no longer pending.');$conn->begin_transaction();$conn->execute_query('UPDATE project_join_requests SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE project_id=? AND user_id=?',[$decision,$user['id'],$project_id,$user_id]);if($decision==='approved')$conn->execute_query('INSERT IGNORE INTO project_members (project_id,user_id) VALUES (?,?)',[$project_id,$user_id]);notify_user($user_id,'Your request to join “'.$request['title'].'” was '.$decision.'.');$conn->commit();flash('Join request '.$decision.'.');go('admin-join-requests.php');}catch(Throwable $e){$conn->rollback();$error=page_error($e);}}
$requests=$conn->query("SELECT r.*,p.title,u.full_name,u.email,u.department,lead.full_name AS lead_name FROM project_join_requests r JOIN projects p ON p.id=r.project_id JOIN users u ON u.id=r.user_id JOIN users lead ON lead.id=p.user_id WHERE r.status='pending' ORDER BY r.created_at")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Join Requests · Admin</title><link rel="stylesheet" href="portal.css"></head><body class="portal-page"><div class="app-container portal-layout"><?php require __DIR__.'/backend/sidebar.php'; ?><main class="main-content"><div class="live-content"><h1>Project join requests</h1><p>Administrative oversight for requests that are normally reviewed by project leads.</p><?php require __DIR__.'/backend/admin_nav.php'; ?><?php if($error): ?><p class="notice error"><?= e($error) ?></p><?php endif; ?><?php if(!$requests): ?><p class="box empty">No join requests are waiting.</p><?php endif; ?><?php foreach($requests as $request): ?><article class="box"><span class="tag">Awaiting review</span><h2><?= e($request['full_name']) ?> → <?= e($request['title']) ?></h2><p class="muted"><?= e($request['department']) ?> · Project lead: <?= e($request['lead_name']) ?></p><?php if($request['message']): ?><p><?= nl2br(e($request['message'])) ?></p><?php endif; ?><form method="post"><input type="hidden" name="project_id" value="<?= (int)$request['project_id'] ?>"><input type="hidden" name="user_id" value="<?= (int)$request['user_id'] ?>"><button name="decision" value="approved">Approve member</button> <button class="danger" name="decision" value="rejected">Decline</button></form></article><?php endforeach; ?></div></main></div></body></html>
